package net.civeira.phylax.feature.observe.observedembed.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observedembed.domain.ObservedEmbed;
import net.civeira.phylax.feature.observe.observedembed.domain.event.ObservedEmbedEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservedEmbedEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservedEmbedEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservedEmbed entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
